{
  "name": "opencode-studio-server",
  "version": "2.5.1",
  "description": "Backend server for OpenCode Studio - manages opencode configurations",
  "main": "index.js",
  "bin": {
    "opencode-studio-server": "cli.js"
  },
  "scripts": {
    "start": "node index.js",
    "register": "node register-protocol.js",
    "postinstall": "node register-protocol.js",
    "test": "node --test profile-manager.test.js lib/*.test.js"
  },
  "keywords": [
    "opencode",
    "studio",
    "config",
    "manager"
  ],
  "author": "Microck",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Microck/opencode-studio.git"
  },
  "type": "commonjs",
  "dependencies": {
    "body-parser": "^2.2.1",
    "cors": "^2.8.5",
    "express": "^5.2.1",
    "js-yaml": "^4.1.1",
    "jsonc-parser": "^3.3.1"
  }
}
